/** 从飞书 post（富文本）content 中提取纯文本，@ 提及转为 @用户名。 */
function extractPostText(contentJson: string): string {
  let parsed: unknown;
  try {
    parsed = JSON.parse(contentJson);
  } catch {
    return "";
  }
  if (parsed == null || typeof parsed !== "object") return "";
  const body = unwrapPostLocale(parsed as Record<string, unknown>);
  if (!body) return "";
  const content = body.content;
  if (!Array.isArray(content)) return "";
  const lines: string[] = [];
  for (const paragraph of content) {
    if (!Array.isArray(paragraph)) continue;
    let line = "";
    for (const el of paragraph) {
      line += renderPostElement(el as Record<string, unknown>);
    }
    lines.push(line);
  }
  return lines.join("\n").trim();
}

const POST_LOCALES = ["zh_cn", "en_us", "ja_jp", "zh_hk", "zh_tw"];

function unwrapPostLocale(parsed: Record<string, unknown>): { title?: unknown; content?: unknown } | null {
  if ("title" in parsed || "content" in parsed) {
    return parsed as { title?: unknown; content?: unknown };
  }
  for (const loc of POST_LOCALES) {
    const hit = parsed[loc];
    if (hit != null && typeof hit === "object") {
      return hit as { title?: unknown; content?: unknown };
    }
  }
  const firstKey = Object.keys(parsed)[0];
  if (firstKey) {
    const first = parsed[firstKey];
    if (first != null && typeof first === "object") {
      return first as { title?: unknown; content?: unknown };
    }
  }
  return null;
}

function renderPostElement(el: Record<string, unknown>): string {
  const tag = el.tag;
  switch (tag) {
    case "text":
      return typeof el.text === "string" ? el.text : "";
    case "at": {
      const name = typeof el.user_name === "string" ? el.user_name : "";
      return name ? `@${name}` : "";
    }
    case "a": {
      const text = typeof el.text === "string" ? el.text : "";
      const href = typeof el.href === "string" ? el.href : "";
      return href ? `[${text || href}](${href})` : text;
    }
    default:
      return typeof el.text === "string" ? el.text : "";
  }
}

/** 先挡自身消息，再做群 @ 门控；bot open_id 缺失时群聊严格 fail-closed。 */
export function parseIncomingEvent(
  event: LarkMessageEvent,
  botOpenId: string | null,
): ParsedIncoming {
  const message = event.message;
  const messageId = message?.message_id ?? null;
  const senderType = event.sender?.sender_type?.toLowerCase() ?? "";
  const senderOpenId = event.sender?.sender_id?.open_id ?? null;

  if (senderType !== "user" || (botOpenId && senderOpenId === botOpenId)) {
    return { kind: "ignore", messageId, reason: "bot_or_app_sender" };
  }
  if (!messageId || !message?.chat_id) {
    return { kind: "ignore", messageId, reason: "missing_identity" };
  }

  const chatType: LarkChatType = message.chat_type === "group" ? "group" : "p2p";
  if (chatType === "group") {
    if (!botOpenId) return { kind: "ignore", messageId, reason: "bot_open_id_missing" };
    if (!isBotMentioned(botOpenId, message.mentions)) {
      return { kind: "ignore", messageId, reason: "not_mentioned" };
    }
  }

  // text 与 post（富文本，含 @ 提及）都走文本通道；其余类型提示不支持。
  let text = "";
  if (message.message_type === "text") {
    try {
      const content = JSON.parse(message.content ?? "{}") as { text?: unknown };
      text = typeof content.text === "string" ? content.text : "";
    } catch {
      return { kind: "ignore", messageId, reason: "invalid_text_content" };
    }
  } else if (message.message_type === "post") {
    text = extractPostText(message.content ?? "{}");
  } else {
    return {
      kind: "message",
      messageId,
      chatId: message.chat_id,
      chatType,
      text: null,
      unsupportedType: message.message_type ?? "unknown",
      senderOpenId,
    };
  }

  if (chatType === "group" && botOpenId) {
    text = stripBotMention(text, botOpenId, message.mentions);
  }
  if (!text.trim()) return { kind: "ignore", messageId, reason: "empty_text" };
  return {
    kind: "message",
    messageId,
    chatId: message.chat_id,
    chatType,
    text,
    unsupportedType: null,
    senderOpenId,
  };
}

