    updateLarkInbox(message.messageId, "ignored");
    return;
  }
  if (message.unsupportedType) {
    await sendLarkText({
      client,
      chatId: message.chatId,
      replyToMessageId: message.messageId,
      markdown: "暂只支持文本。",
    });
