    chat_id?: string;
    chat_type?: string;
    message_type?: string;
    content?: string;
    mentions?: LarkMention[];
  };
};

export type ParsedIncoming =
  | { kind: "ignore"; messageId: string | null; reason: string }
  | {
      kind: "message";
      messageId: string;
      chatId: string;
